mapper.select:
SELECT t.id, t.task_no, t.task_type, t.warehouse_id, w.code AS warehouse_code, w.name AS warehouse_name, t.material_id, m.code AS material_code, m.name AS material_name, t.batch_no, t.qty, t.location_id, l.code AS location_code, t.from_location_id, fl.code AS from_location_code, t.wave_id, v.wave_no, t.source_type, t.source_no, t.assignee, u.nickname AS assignee_name, t.status, t.recommend_reason, t.finish_time, t.remark, t.create_time FROM wms_task t LEFT JOIN base_warehouse w ON w.id = t.warehouse_id LEFT JOIN base_material m ON m.id = t.material_id LEFT JOIN base_location l ON l.id = t.location_id LEFT JOIN base_location fl ON fl.id = t.from_location_id LEFT JOIN wms_wave v ON v.id = t.wave_id LEFT JOIN sys_user u ON u.id = t.assignee AND u.deleted = 0 WHERE t.deleted = 0
AND t.task_type = #{q.taskType}
AND t.status = #{q.status}
AND t.warehouse_id = #{q.warehouseId}
AND t.assignee = #{q.assignee}
AND (t.task_no LIKE CONCAT('%', #{q.keyword}, '%') OR t.source_no LIKE CONCAT('%', #{q.keyword}, '%') OR m.code LIKE CONCAT('%', #{q.keyword}, '%') OR m.name LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY t.id DESC

SELECT t.task_type AS task_type, t.status AS status, COUNT(*) AS cnt FROM wms_task t WHERE t.deleted = 0 AND t.status < 30
AND t.warehouse_id = #{warehouseId}
GROUP BY t.task_type, t.status

SELECT c.doc_id, c.source_type, c.doc_no, c.warehouse_id, COUNT(*) AS line_count, SUM(c.qty) AS total_qty, MAX(c.audit_time) AS audit_time FROM ( SELECT h.id AS doc_id, 'SAL_OUT' AS source_type, h.out_no AS doc_no, h.warehouse_id, d.material_id, d.qty, h.audit_time FROM sal_outstock h JOIN sal_outstock_detail d ON d.out_id = h.id AND d.deleted = 0 WHERE h.deleted = 0 AND h.status = 10 AND h.audit_time >= DATE_SUB(NOW(), INTERVAL #{daysBack} DAY) UNION ALL SELECT h.id, 'OTH_OUT', h.no, h.warehouse_id, l.material_id, l.qty, h.audit_time FROM inv_other_out h JOIN inv_other_out_line l ON l.other_out_id = h.id AND l.deleted = 0 WHERE h.deleted = 0 AND h.status = 1 AND h.audit_time >= DATE_SUB(NOW(), INTERVAL #{daysBack} DAY) ) c WHERE NOT EXISTS ( SELECT 1 FROM wms_task t WHERE t.deleted = 0 AND t.status != 40 AND t.task_type = 'PICK' AND t.source_type = c.source_type AND t.source_id = c.doc_id)
AND c.warehouse_id = #{warehouseId}
GROUP BY c.doc_id, c.source_type, c.doc_no, c.warehouse_id ORDER BY MAX(c.audit_time) DESC LIMIT 100
